import requests


def _rebuild(url, proxies, trust_env=False):
    """helper: rebuild proxies for url and return prepared request"""
    session = requests.Session()
    session.trust_env = trust_env
    req = requests.Request('GET', url)
    prep = req.prepare()
    session.rebuild_proxies(prep, proxies)
    return prep


